"""Run Synthea with a fixed seed so a cohort can be regenerated byte for byte.

A cohort is named after its seed (``c20261118``). The population seed, the
clinician seed and the reference date are all pinned, because Synthea's output
depends on all three and on nothing else once the module set is fixed.
"""

from __future__ import annotations

import hashlib
import json
import subprocess
import sys
import urllib.request
from dataclasses import dataclass
from datetime import date
from pathlib import Path

from ces.config import SYNTHEA_JAR_SHA256, SYNTHEA_JAR_URL, Settings


@dataclass(frozen=True)
class Cohort:
    seed: int
    patients: int
    reference_date: date
    state: str = "Missouri"

    @property
    def id(self) -> str:
        return f"c{self.seed}"


def cohort_for_week(day: date, patients: int) -> Cohort:
    """The weekly refresh generates one cohort per ISO week, seeded by that week,
    with the reference date on the Monday. Running it twice in a week is a no-op."""
    iso_year, iso_week, _ = day.isocalendar()
    monday = date.fromisocalendar(iso_year, iso_week, 1)
    return Cohort(seed=int(f"{iso_year}{iso_week:02d}"), patients=patients, reference_date=monday)


def sha256_of(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def ensure_jar(cfg: Settings, log=print) -> Path:
    jar = cfg.jar_path
    if jar.exists() and sha256_of(jar) == SYNTHEA_JAR_SHA256:
        return jar
    jar.parent.mkdir(parents=True, exist_ok=True)
    log(f"downloading Synthea {SYNTHEA_JAR_URL}")
    tmp = jar.with_suffix(".part")
    urllib.request.urlretrieve(SYNTHEA_JAR_URL, tmp)  # noqa: S310 - fixed https URL
    got = sha256_of(tmp)
    if got != SYNTHEA_JAR_SHA256:
        tmp.unlink(missing_ok=True)
        raise RuntimeError(f"Synthea jar checksum mismatch: {got}")
    tmp.replace(jar)
    return jar


def cohort_dir(cfg: Settings, cohort: Cohort) -> Path:
    return cfg.raw_dir / cohort.id


def generate(cfg: Settings, cohort: Cohort, log=print) -> Path:
    """Generate the cohort unless its marker says it is already complete."""
    out = cohort_dir(cfg, cohort)
    marker = out / "cohort.json"
    if marker.exists():
        log(f"cohort {cohort.id} already generated, skipping")
        return out
    jar = ensure_jar(cfg, log)
    out.mkdir(parents=True, exist_ok=True)
    cmd = [
        "java",
        *cfg.java_opts.split(),
        "-jar",
        str(jar),
        "-p",
        str(cohort.patients),
        "-s",
        str(cohort.seed),
        "-cs",
        str(cohort.seed),
        "-r",
        cohort.reference_date.strftime("%Y%m%d"),
        f"--exporter.baseDirectory={out.as_posix()}/",
        "--exporter.fhir.export=true",
        "--exporter.hospital.fhir.export=false",
        "--exporter.practitioner.fhir.export=false",
        "--exporter.csv.export=false",
        "--generate.only_alive_patients=false",
        cohort.state,
    ]
    log(f"generating cohort {cohort.id}: {cohort.patients} patients, seed {cohort.seed}")
    with (out / "synthea.log").open("w", encoding="utf-8") as logf:
        proc = subprocess.run(cmd, stdout=logf, stderr=subprocess.STDOUT, check=False)
    if proc.returncode != 0:
        raise RuntimeError(f"Synthea exited {proc.returncode}; see {out / 'synthea.log'}")
    files = sorted((out / "fhir").glob("*.json"))
    if not files:
        raise RuntimeError("Synthea produced no FHIR bundles")
    marker.write_text(
        json.dumps(
            {
                "cohort_id": cohort.id,
                "seed": cohort.seed,
                "patients_requested": cohort.patients,
                "bundles": len(files),
                "reference_date": cohort.reference_date.isoformat(),
                "state": cohort.state,
                "synthea_jar_sha256": SYNTHEA_JAR_SHA256,
                "python": sys.version.split()[0],
            },
            indent=1,
        ),
        encoding="utf-8",
    )
    log(f"cohort {cohort.id}: {len(files)} bundles")
    return out
